derivation_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials
WHERE "Name of ICI" = 'Nivolumab' AND "Cancer type" = 'Non-Small Cell Lung' AND "Control arm" = 'Chemo'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_backbone(source_value) AS "control_backbone"
FROM base;
